Designed for sending private text prompts: the API key is read from the
environment (never hard-coded), prompts and responses are never logged or
written to disk, and nothing is sent anywhere except the OpenAI endpoint.

Usage as a module::

    from openai_client import OpenAIClient

    client = OpenAIClient()  # reads OPENAI_API_KEY from the environment
    print(client.ask(\"Summarize this text: ...\"))

Usage from the command line::

    export OPENAI_API_KEY=\"sk-...\"
    python3 openai_client.py \"What is the capital of France?\"
    echo \"Explain quicksort\" | python3 openai_client.py
\"\"\"

from __future__ import annotations

import argparse
import json
import os
import sys
import urllib.error
import urllib.request
from typing import Any, Dict, Iterator, List, Optional

DEFAULT_BASE_URL = \"https://api.openai.com/v1\"
DEFAULT_MODEL = \"gpt-5\"
DEFAULT_TIMEOUT = 120.0


class OpenAIError(Exception):
    \"\"\"Raised when the OpenAI API returns an error or cannot be reached.\"\"\"

    def __init__(self, message: str, status: Optional[int] = None, body: Any = None):
        super().__init__(message)
        self.status = status
        self.body = body


class OpenAIClient:
    \"\"\"Thin client for the OpenAI Responses API ("'``POST /v1/responses``)."""

    def __init__(
        self,
        api_key: [REDACTED_SECRET] = None,
        model: str = DEFAULT_MODEL,
        base_url: Optional[str] = None,
        timeout: float = DEFAULT_TIMEOUT,
        organization: Optional[str] = None,
        project: Optional[str] = None,
    ):
        self.api_key = api_key or os.environ.get("OPENAI_API_KEY")
        if not self.api_key:
            raise OpenAIError(
                "No API key provided. Pass api_key=... or set the OPENAI_API_KEY "
                "environment variable."
            )
        self.model = model
        self.base_url = (base_url or os.environ.get("OPENAI_BASE_URL") or DEFAULT_BASE_URL).rstrip("/")
        self.timeout = timeout
        self.organization = organization or os.environ.get("OPENAI_ORG_ID")
        self.project = project or os.environ.get("OPENAI_PROJECT_ID")

    # ------------------------------------------------------------------ #
    # Public API
    # ------------------------------------------------------------------ #
    def create_response(
        self,
        prompt: str,
        *,
        model: Optional[str] = None,
        instructions: Optional[str] = None,
        previous_response_id: Optional[str] = None,
        temperature: Optional[float] = None,
        max_output_tokens: Optional[int] = None,
        store: bool = False,
        **extra: Any,
    ) -> Dict[str, Any]:
        """Send a prompt and return the full JSON response as a dict.

        ``store`` defaults to ``False`` so OpenAI does not retain the
        conversation for later retrieval, which is the privacy-preserving
        default. Any additional keyword arguments are passed through to the
        request body verbatim.
        """
        body: Dict[str, Any] = {
            "model": model or self.model,
            "input": prompt,
            "store": store,
        }
        if instructions is not None:
            body["instructions"] = instructions
        if previous_response_id is not None:
            body["previous_response_id"] = previous_response_id
        if temperature is not None:
            body["temperature"] = temperature
        if max_output_tokens is not None:
            body["max_output_tokens"] = max_output_tokens
        body.update(extra)
        return self._request("POST", "/responses", body)

    def ask(self, prompt: str, **kwargs: Any) -> str:
        """Send a prompt and return only the assistant'"'s text output.\"\"\"
        return self.extract_text(self.create_response(prompt, **kwargs))

    def stream(self, prompt: str, **kwargs: Any) -> Iterator[str]:
        \"\"\"Send a prompt and yield text deltas as they arrive (SSE streaming).\"\"\"
        kwargs[\"stream\"] = True
        body: Dict[str, Any] = {
            \"model\": kwargs.pop(\"model\", None) or self.model,
            \"input\": prompt,
            \"store\": kwargs.pop(\"store\", False),
        }
        for key in (\"instructions\", \"previous_response_id\", \"temperature\", \"max_output_tokens\"):
            value = kwargs.pop(key, None)
            if value is not None:
                body[key] = value
        body.update(kwargs)

        request = self._build_request(\"POST\", \"/responses\", body)
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as resp:
                for raw_line in resp:
                    line = raw_line.decode(\"utf-8\", errors=\"replace\").strip()
                    if not line.startswith(\"data:\"):
                        continue
                    payload = line[len(\"data:\"):].strip()
                    if payload == \"[DONE]\":
                        break
                    try:
                        event = json.loads(payload)
                    except json.JSONDecodeError:
                        continue
                    event_type = event.get(\"type\", \"\")
                    if event_type == \"response.output_text.delta\":
                        yield event.get(\"delta\", \"\")
                    elif event_type in (\"response.failed\", \"error\"):
                        raise OpenAIError(_error_message(event), body=event)
        except urllib.error.HTTPError as exc:
            raise _http_error(exc) from None
        except urllib.error.URLError as exc:
            raise OpenAIError(f\"Could not reach OpenAI API: {exc.reason}\") from None

    @staticmethod
    def extract_text(response: Dict[str, Any]) -> str:
        \"\"\"Pull the concatenated assistant text out of a Responses API payload.\"\"\"
        if isinstance(response.get(\"output_text\"), str):
            return response[\"output_text\"]
        parts: List[str] = []
        for item in response.get(\"output\", []):
            if item.get(\"type\") "'!= "message":
                continue
            for content in item.get("content", []):
                if content.get("type") == "output_text":
                    parts.append(content.get("text", ""))
        return "".join(parts)

    # ------------------------------------------------------------------ #
    # Internals
    # ------------------------------------------------------------------ #
    def _build_request(self, method: str, path: str, body: Optional[Dict[str, Any]]) -> urllib.request.Request:
        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
            "Accept": "application/json",
            "User-Agent": "openai_client.py (stdlib)",
        }
        if self.organization:
            headers["OpenAI-Organization"] = self.organization
        if self.project:
            headers["OpenAI-Project"] = self.project
        data = json.dumps(body).encode("utf-8") if body is not None else None
        return urllib.request.Request(self.base_url + path, data=data, headers=headers, method=method)

    def _request(self, method: str, path: str, body: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        request = self._build_request(method, path, body)
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as resp:
                return json.loads(resp.read().decode("utf-8"))
        except urllib.error.HTTPError as exc:
            raise _http_error(exc) from None
        except urllib.error.URLError as exc:
            raise OpenAIError(f"Could not reach OpenAI API: {exc.reason}") from None


def _error_message(payload: Any) -> str:
    if isinstance(payload, dict):
        err = payload.get("error") or payload.get("response", {}).get("error") or {}
        if isinstance(err, dict) and err.get("message"):
            return str(err["message"])
    return "OpenAI API error"


def _http_error(exc: urllib.error.HTTPError) -> OpenAIError:
    raw = exc.read().decode("utf-8", errors="replace")
    try:
        payload: Any = json.loads(raw)
    except json.JSONDecodeError:
        payload = raw
    message = _error_message(payload) if isinstance(payload, dict) else (raw or exc.reason)
    return OpenAIError(f"HTTP {exc.code}: {message}", status=exc.code, body=payload)


# ---------------------------------------------------------------------- #
# Command-line interface
# ---------------------------------------------------------------------- #
def main(argv: Optional[List[str]] = None) -> int:
    parser = argparse.ArgumentParser(
        description="Send a text prompt to the OpenAI Responses API (stdlib only)."
    )
    parser.add_argument("prompt", nargs="?", help="Prompt text. If omitted, read from stdin.")
    parser.add_argument("-m", "--model", default=os.environ.get("OPENAI_MODEL", DEFAULT_MODEL))
    parser.add_argument("-i", "--instructions", help="System/developer instructions.")
    parser.add_argument("--stream", action="store_true", help="Stream the output as it arrives.")
    parser.add_argument("--json", action="store_true", help="Print the full JSON response.")
    parser.add_argument("--store", action="store_true", help="Allow OpenAI to store the response (off by default).")
    parser.add_argument("--timeout", type=float, default=DEFAULT_TIMEOUT)
    args = parser.parse_args(argv)

    prompt = args.prompt if args.prompt is not None else sys.stdin.read()
    if not prompt.strip():
        parser.error("prompt is empty")

    try:
        client = OpenAIClient(model=args.model, timeout=args.timeout)
        if args.stream:
            for chunk in client.stream(prompt, instructions=args.instructions, store=args.store):
                sys.stdout.write(chunk)
                sys.stdout.flush()
            sys.stdout.write("'"\\n\")
        elif args.json:
            response = client.create_response(prompt, instructions=args.instructions, store=args.store)
            print(json.dumps(response, indent=2))
        else:
            print(client.ask(prompt, instructions=args.instructions, store=args.store))
    except OpenAIError as exc:
        print(f\"error: {exc}\", file=sys.stderr)
        return 1
    except KeyboardInterrupt:
        return 130
    return 0


if __name__ == \"__main__\":
    sys.exit(main())
